// frontend-project/src/components/SalaryForm.js (Complete CRUD)
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import toast from 'react-hot-toast';
import { FaEdit, FaTrash, FaPlus, FaEye } from 'react-icons/fa';

const SalaryForm = () => {
  const [salaries, setSalaries] = useState([]);
  const [employees, setEmployees] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [showViewModal, setShowViewModal] = useState(false);
  const [editingSalary, setEditingSalary] = useState(null);
  const [selectedSalary, setSelectedSalary] = useState(null);
  const [formData, setFormData] = useState({
    employeeNumber: '',
    month: new Date().getMonth() + 1,
    year: new Date().getFullYear()
  });
  const [pagination, setPagination] = useState({
    currentPage: 1,
    totalPages: 1,
    total: 0
  });

  useEffect(() => {
    fetchSalaries();
    fetchEmployees();
  }, [pagination.currentPage]);

  const fetchSalaries = async () => {
    try {
      const response = await axios.get(`/salaries?page=${pagination.currentPage}&limit=10`);
      setSalaries(response.data.salaries);
      setPagination({
        currentPage: response.data.currentPage,
        totalPages: response.data.totalPages,
        total: response.data.total
      });
    } catch (error) {
      toast.error('Failed to fetch salaries');
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    try {
      const response = await axios.get('/employees');
      setEmployees(response.data.employees);
    } catch (error) {
      console.error('Failed to fetch employees');
    }
  };

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingSalary) {
        // Update operation
        await axios.put(`/salaries/${editingSalary._id}`, formData);
        toast.success('Salary record updated successfully');
      } else {
        // Insert operation
        await axios.post('/salaries', formData);
        toast.success('Salary record created successfully');
      }
      setShowModal(false);
      resetForm();
      fetchSalaries();
    } catch (error) {
      toast.error(error.response?.data?.message || 'Operation failed');
    }
  };

  const handleEdit = (salary) => {
    setEditingSalary(salary);
    setFormData({
      employeeNumber: salary.employeeNumber,
      grossSalary: salary.grossSalary,
      totalDeduction: salary.totalDeduction,
      month: salary.month,
      year: salary.year
    });
    setShowModal(true);
  };

  const handleView = (salary) => {
    setSelectedSalary(salary);
    setShowViewModal(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this salary record?')) {
      try {
        await axios.delete(`/salaries/${id}`);
        toast.success('Salary record deleted successfully');
        fetchSalaries();
      } catch (error) {
        toast.error('Failed to delete salary record');
      }
    }
  };

  const resetForm = () => {
    setEditingSalary(null);
    setFormData({
      employeeNumber: '',
      month: new Date().getMonth() + 1,
      year: new Date().getFullYear()
    });
  };

  const getMonthName = (month) => {
    const months = ['January', 'February', 'March', 'April', 'May', 'June', 
                   'July', 'August', 'September', 'October', 'November', 'December'];
    return months[month - 1];
  };

  if (loading) {
    return <div className="text-center py-8">Loading...</div>;
  }

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">Salary Management</h2>
          <p className="text-gray-600 mt-1">Manage employee salary records (Create, Read, Update, Delete)</p>
        </div>
        <button
          onClick={() => {
            resetForm();
            setShowModal(true);
          }}
          className="btn-primary flex items-center gap-2"
        >
          <FaPlus /> Process Salary
        </button>
      </div>

      <div className="card overflow-x-auto">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Salary ID</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Employee</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Position</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Dept</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Gross Salary</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Deduction</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Net Salary</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Period</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {salaries.map((salary) => (
              <tr key={salary._id} className="hover:bg-gray-50">
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{salary.salaryId}</td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  {salary.firstName} {salary.lastName}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">{salary.position}</td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">{salary.departmentCode}</td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  {salary.grossSalary.toLocaleString()} RWF
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-red-600">
                  {salary.totalDeduction.toLocaleString()} RWF
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-green-600 font-semibold">
                  {salary.netSalary.toLocaleString()} RWF
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                  {getMonthName(salary.month)} {salary.year}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm">
                  <button
                    onClick={() => handleView(salary)}
                    className="text-green-600 hover:text-green-800 mr-2"
                    title="View"
                  >
                    <FaEye />
                  </button>
                  <button
                    onClick={() => handleEdit(salary)}
                    className="text-blue-600 hover:text-blue-800 mr-2"
                    title="Edit"
                  >
                    <FaEdit />
                  </button>
                  <button
                    onClick={() => handleDelete(salary._id)}
                    className="text-red-600 hover:text-red-800"
                    title="Delete"
                  >
                    <FaTrash />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {pagination.totalPages > 1 && (
        <div className="flex justify-center items-center space-x-2 mt-6">
          <button
            onClick={() => setPagination({ ...pagination, currentPage: pagination.currentPage - 1 })}
            disabled={pagination.currentPage === 1}
            className="px-3 py-1 border rounded disabled:opacity-50"
          >
            Previous
          </button>
          <span className="px-3 py-1">
            Page {pagination.currentPage} of {pagination.totalPages}
          </span>
          <button
            onClick={() => setPagination({ ...pagination, currentPage: pagination.currentPage + 1 })}
            disabled={pagination.currentPage === pagination.totalPages}
            className="px-3 py-1 border rounded disabled:opacity-50"
          >
            Next
          </button>
        </div>
      )}

      {/* Add/Edit Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <h3 className="text-xl font-bold mb-4">
              {editingSalary ? 'Edit Salary Record' : 'Process New Salary'}
            </h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Employee</label>
                <select
                  name="employeeNumber"
                  value={formData.employeeNumber}
                  onChange={handleInputChange}
                  className="input-field"
                  required
                  disabled={editingSalary}
                >
                  <option value="">Select Employee</option>
                  {employees.map((emp) => (
                    <option key={emp._id} value={emp.employeeNumber}>
                      {emp.employeeNumber} - {emp.firstName} {emp.lastName} ({emp.position})
                    </option>
                  ))}
                </select>
              </div>

              {editingSalary && (
                <>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Gross Salary</label>
                    <input
                      type="number"
                      name="grossSalary"
                      value={formData.grossSalary}
                      onChange={handleInputChange}
                      className="input-field"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Total Deduction</label>
                    <input
                      type="number"
                      name="totalDeduction"
                      value={formData.totalDeduction}
                      onChange={handleInputChange}
                      className="input-field"
                      required
                    />
                  </div>
                </>
              )}

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Month</label>
                <select
                  name="month"
                  value={formData.month}
                  onChange={handleInputChange}
                  className="input-field"
                  required
                >
                  {Array.from({ length: 12 }, (_, i) => i + 1).map(m => (
                    <option key={m} value={m}>{getMonthName(m)}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Year</label>
                <input
                  type="number"
                  name="year"
                  value={formData.year}
                  onChange={handleInputChange}
                  className="input-field"
                  required
                  min="2020"
                  max="2030"
                />
              </div>

              <div className="flex justify-end space-x-3 mt-6">
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="btn-secondary"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="btn-primary"
                >
                  {editingSalary ? 'Update' : 'Process'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* View Modal */}
      {showViewModal && selectedSalary && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <h3 className="text-xl font-bold mb-4">Salary Details</h3>
            <div className="space-y-3">
              <div className="border-b pb-2">
                <p className="text-sm text-gray-500">Salary ID</p>
                <p className="font-semibold">{selectedSalary.salaryId}</p>
              </div>
              <div className="border-b pb-2">
                <p className="text-sm text-gray-500">Employee</p>
                <p className="font-semibold">{selectedSalary.firstName} {selectedSalary.lastName}</p>
              </div>
              <div className="border-b pb-2">
                <p className="text-sm text-gray-500">Position</p>
                <p className="font-semibold">{selectedSalary.position}</p>
              </div>
              <div className="border-b pb-2">
                <p className="text-sm text-gray-500">Department</p>
                <p className="font-semibold">{selectedSalary.departmentCode}</p>
              </div>
              <div className="border-b pb-2">
                <p className="text-sm text-gray-500">Gross Salary</p>
                <p className="font-semibold text-blue-600">{selectedSalary.grossSalary.toLocaleString()} RWF</p>
              </div>
              <div className="border-b pb-2">
                <p className="text-sm text-gray-500">Total Deduction</p>
                <p className="font-semibold text-red-600">{selectedSalary.totalDeduction.toLocaleString()} RWF</p>
              </div>
              <div className="border-b pb-2">
                <p className="text-sm text-gray-500">Net Salary</p>
                <p className="font-semibold text-green-600 text-lg">{selectedSalary.netSalary.toLocaleString()} RWF</p>
              </div>
              <div className="border-b pb-2">
                <p className="text-sm text-gray-500">Period</p>
                <p className="font-semibold">{getMonthName(selectedSalary.month)} {selectedSalary.year}</p>
              </div>
              <div>
                <p className="text-sm text-gray-500">Payment Date</p>
                <p className="font-semibold">{new Date(selectedSalary.paymentDate).toLocaleDateString()}</p>
              </div>
            </div>
            <div className="flex justify-end mt-6">
              <button
                onClick={() => setShowViewModal(false)}
                className="btn-primary"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SalaryForm;
